/**
 * Pure function: Validate and Normalize Support Ticket Request
 * Ciketo Logistics ElevenLabs Support Ticket Handoff
 */

function simpleHash(str) {
  let hash = 5381;
  const s = String(str || '');
  for (let i = 0; i < s.length; i++) {
    hash = ((hash << 5) + hash) + s.charCodeAt(i);
    hash = hash & hash; // Convert to 32bit integer
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

const VALID_CATEGORIES = new Set([
  'unanswered_question',
  'complaint',
  'delay',
  'damage_claim',
  'billing',
  'quote_followup',
  'callback_request',
  'customs_legal',
  'other'
]);

const VALID_PRIORITIES = new Set([
  'low',
  'normal',
  'high',
  'urgent'
]);

const URGENT_REGEX = /\b(urgent|asap|emergency|lost|stolen)\b/i;

function normalizeTicketRequest(body, config = {}) {
  // Reject bodies with wrong types or exceeding expected size
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return {
      valid: false,
      validation_message: 'Request body must be a valid JSON object.'
    };
  }

  let bodyStr = '';
  try {
    bodyStr = JSON.stringify(body);
  } catch (e) {
    return {
      valid: false,
      validation_message: 'Request body contains invalid or unparseable JSON.'
    };
  }

  if (bodyStr.length > 50000) {
    return {
      valid: false,
      validation_message: 'Request body exceeds maximum allowed size.'
    };
  }

  // Trim and extract raw values
  function cleanStr(val) {
    if (val === undefined || val === null) return '';
    return String(val).trim();
  }

  const rawConvId = cleanStr(body.conversation_id);
  const rawName = cleanStr(body.customer_name);
  const rawEmail = cleanStr(body.email);
  const rawPhone = cleanStr(body.phone);
  const rawOrderId = cleanStr(body.order_id);
  const rawCategory = cleanStr(body.category).toLowerCase();
  const rawPriority = cleanStr(body.priority).toLowerCase();
  const rawSummary = cleanStr(body.summary);
  const rawDetails = cleanStr(body.details);

  // 1. Validate conversation_id (required, string starting with "conv_")
  if (!rawConvId || !rawConvId.startsWith('conv_') || rawConvId.length < 6) {
    return {
      valid: false,
      validation_message: 'A valid conversation ID starting with conv_ is required.'
    };
  }

  // 2. Validate customer_name (required)
  if (!rawName) {
    return {
      valid: false,
      validation_message: 'Customer name is required.'
    };
  }

  // 3. Normalize email
  let email = null;
  if (rawEmail) {
    const cleanedEmail = rawEmail.toLowerCase();
    if (cleanedEmail.includes('@') && cleanedEmail.includes('.')) {
      email = cleanedEmail;
    }
  }

  // 4. Normalize phone (keeps digits and a leading +)
  let phone = null;
  if (rawPhone) {
    const hasLeadingPlus = rawPhone.startsWith('+');
    const digits = rawPhone.replace(/\D/g, '');
    if (digits.length > 0) {
      phone = (hasLeadingPlus ? '+' : '') + digits;
    }
  }

  // 5. Email or Phone rule (at least one is required)
  if (!email && !phone) {
    return {
      valid: false,
      validation_message: 'At least one valid contact method (email or phone) is required.'
    };
  }

  // 6. Summary validation (required, 3 to 200 chars)
  if (!rawSummary || rawSummary.length < 3) {
    return {
      valid: false,
      validation_message: 'Summary must be at least 3 characters long.'
    };
  }
  const summary = rawSummary.slice(0, 200);

  // 7. Details validation (required, at least 5 chars, truncate to 4000)
  if (!rawDetails || rawDetails.length < 5) {
    return {
      valid: false,
      validation_message: 'Details must be at least 5 characters long.'
    };
  }
  const details = rawDetails.slice(0, 4000);

  // 8. Order ID normalization (upper-cases and trims)
  const orderId = rawOrderId ? rawOrderId.toUpperCase() : null;

  // 9. Coerce unknown category to "other"
  let category = VALID_CATEGORIES.has(rawCategory) ? rawCategory : 'other';

  // 10. Coerce unknown priority to "normal"
  let priority = VALID_PRIORITIES.has(rawPriority) ? rawPriority : 'normal';

  // 11. Priority elevation rules:
  // - Raises priority to at least "high" when category is damage_claim or delay
  if (category === 'damage_claim' || category === 'delay') {
    if (priority === 'low' || priority === 'normal') {
      priority = 'high';
    }
  }

  // - Raises priority to "high" when details contain urgent words (urgent, asap, emergency, lost, stolen)
  if (URGENT_REGEX.test(details)) {
    if (priority === 'low' || priority === 'normal') {
      priority = 'high';
    }
  }

  // 12. Build dedupe_key from conversation_id, category and simple string hash of lower-cased summary
  const summaryHash = simpleHash(summary.toLowerCase());
  const dedupeKey = `${rawConvId}:${category}:${summaryHash}`;

  return {
    valid: true,
    validation_message: 'Validation passed.',
    conversation_id: rawConvId,
    customer_name: rawName,
    email: email,
    phone: phone,
    order_id: orderId,
    category: category,
    priority: priority,
    summary: summary,
    details: details,
    dedupe_key: dedupeKey,
    // Configuration values passed down
    SUPABASE_URL: config.SUPABASE_URL || 'https://YOUR-PROJECT.supabase.co',
    TRANSCRIPT_MAX_CHARS: config.TRANSCRIPT_MAX_CHARS || 20000,
    FETCH_ATTEMPTS: config.FETCH_ATTEMPTS || 3
  };
}

// Module export for Node.js unit tests
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    simpleHash,
    normalizeTicketRequest
  };
}

// n8n Code node runtime execution
if (typeof $input !== 'undefined') {
  const item = $input.first().json || {};
  const rawBody = item.body || item;
  let config = {};
  try {
    config = $('Config').first().json || {};
  } catch (e) {
    config = {};
  }
  const result = normalizeTicketRequest(rawBody, config);
  return [{ json: result }];
}

/**
 * Pure function: Verify Identity Against Order Lookup
 * Ciketo Logistics ElevenLabs Support Ticket Handoff
 */

function verifyIdentity(ticket, orderLookupResult) {
  const t = ticket || {};
  let orders = [];

  if (Array.isArray(orderLookupResult)) {
    orders = orderLookupResult;
  } else if (orderLookupResult && typeof orderLookupResult === 'object') {
    if (Array.isArray(orderLookupResult.body)) {
      orders = orderLookupResult.body;
    } else if (orderLookupResult.id || orderLookupResult.order_id) {
      orders = [orderLookupResult];
    }
  }

  let orderUuid = null;
  let identityVerified = false;

  // order_uuid if exactly one order matched
  if (orders.length === 1 && orders[0] && (orders[0].id || orders[0].order_id)) {
    const matchedOrder = orders[0];
    orderUuid = matchedOrder.id || null;

    // identity_verified true only when the order matched and:
    // 1. ticket email equals the order email (case-insensitive)
    const ticketEmail = (t.email || '').toLowerCase().trim();
    const orderEmail = (matchedOrder.email || '').toLowerCase().trim();
    const emailMatches = Boolean(ticketEmail && orderEmail && ticketEmail === orderEmail);

    // 2. OR the last 7 digits of the phones match
    const ticketDigits = (t.phone || '').replace(/\D/g, '');
    const orderDigits = (matchedOrder.phone || '').replace(/\D/g, '');
    const phoneMatches = Boolean(
      ticketDigits.length >= 7 &&
      orderDigits.length >= 7 &&
      ticketDigits.slice(-7) === orderDigits.slice(-7)
    );

    identityVerified = emailMatches || phoneMatches;
  }

  return {
    customer_name: t.customer_name || '',
    email: t.email || null,
    phone: t.phone || null,
    order_id: t.order_id || null,
    order_uuid: orderUuid,
    category: t.category || 'other',
    priority: t.priority || 'normal',
    summary: t.summary || '',
    details: t.details || '',
    source: 'chat_agent',
    is_handoff: true,
    identity_verified: identityVerified,
    conversation_id: t.conversation_id || '',
    dedupe_key: t.dedupe_key || ''
  };
}

// Module export for Node.js unit tests
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    verifyIdentity
  };
}

// n8n Code node runtime execution
if (typeof $input !== 'undefined') {
  let ticket = {};
  try {
    ticket = $('Validate and Normalize').first().json || {};
  } catch (e) {
    ticket = $input.first().json || {};
  }

  let orderLookup = [];
  try {
    const lookupNode = $('Lookup Order');
    if (lookupNode && lookupNode.all) {
      orderLookup = lookupNode.all().map(i => i.json);
    }
  } catch (e) {
    orderLookup = [];
  }

  const result = verifyIdentity(ticket, orderLookup);
  return [{ json: result }];
}

/**
 * Pure function: Build Transcript from ElevenLabs Conversation
 * Ciketo Logistics ElevenLabs Support Ticket Handoff
 */

function buildTranscript(conversationData, options = {}) {
  const attempt = Number(options.attempt) || 1;
  const maxAttempts = Number(options.maxAttempts) || 3;
  const maxChars = Number(options.maxChars) || 20000;

  const data = conversationData || {};
  const hasError = Boolean(
    data.error ||
    (data.statusCode && data.statusCode >= 400) ||
    (data.status && data.status >= 400)
  );

  let rawTranscript = null;
  if (!hasError && Array.isArray(data.transcript)) {
    rawTranscript = data.transcript;
  } else if (!hasError && data.body && Array.isArray(data.body.transcript)) {
    rawTranscript = data.body.transcript;
  }

  // Handle fetch failure or missing transcript array
  if (hasError || rawTranscript === null) {
    if (attempt < maxAttempts) {
      return {
        should_retry: true,
        attempt: attempt + 1,
        transcript_text: '',
        note_kind: 'system',
        has_user_message: false
      };
    }
    return {
      should_retry: false,
      attempt: attempt,
      transcript_text: 'Transcript could not be retrieved.',
      note_kind: 'system',
      has_user_message: false
    };
  }

  // Process transcript entries
  const lines = [];
  let hasUserMessage = false;

  for (const entry of rawTranscript) {
    if (!entry || entry.message === null || entry.message === undefined) {
      continue;
    }

    const msg = String(entry.message).trim();
    if (!msg) {
      continue;
    }

    const role = String(entry.role || '').toLowerCase();
    if (role === 'user') {
      hasUserMessage = true;
      lines.push('Customer: ' + msg);
    } else if (role === 'agent') {
      lines.push('Agent: ' + msg);
    } else {
      lines.push('System: ' + msg);
    }
  }

  // If transcript was empty or only contained null/empty messages
  if (lines.length === 0) {
    if (attempt < maxAttempts) {
      return {
        should_retry: true,
        attempt: attempt + 1,
        transcript_text: '',
        note_kind: 'system',
        has_user_message: false
      };
    }
    return {
      should_retry: false,
      attempt: attempt,
      transcript_text: 'Transcript could not be retrieved.',
      note_kind: 'system',
      has_user_message: false
    };
  }

  let text = lines.join('\n');

  // Truncate to maxChars with [truncated] marker if exceeded
  if (text.length > maxChars) {
    const marker = '\n[truncated]';
    const sliceLen = Math.max(0, maxChars - marker.length);
    text = text.slice(0, sliceLen) + marker;
  }

  return {
    should_retry: false,
    attempt: attempt,
    transcript_text: text,
    note_kind: 'transcript',
    has_user_message: hasUserMessage
  };
}

// Module export for Node.js unit tests
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    buildTranscript
  };
}

// n8n Code node runtime execution
if (typeof $input !== 'undefined') {
  const convData = $input.first().json || {};
  let cfg = {};
  try {
    cfg = $('Config').first().json || {};
  } catch (e) {
    cfg = {};
  }

  let attempt = 1;
  try {
    const prevAttempt = $('Init Attempt').first().json.attempt;
    if (prevAttempt) attempt = Number(prevAttempt);
  } catch (e) {
    attempt = 1;
  }

  // Check if we are in a retry loop and attempt was already updated
  try {
    const lastAttempt = $('Build Transcript').first().json.attempt;
    if (lastAttempt && Number(lastAttempt) > attempt) {
      attempt = Number(lastAttempt);
    }
  } catch (e) {
    // first run
  }

  const maxChars = cfg.TRANSCRIPT_MAX_CHARS || 20000;
  const maxAttempts = cfg.FETCH_ATTEMPTS || 3;

  const result = buildTranscript(convData, { attempt, maxAttempts, maxChars });
  return [{ json: result }];
}
